public final class Pricing {
    private Pricing() {}

    public static double discountRate(String tier) {
        if (tier.equals("bronze")) return 0.00;
        else if (tier.equals("silver")) return 0.05;
        else if (tier.equals("gold")) return 0.10;
        else if (tier.equals("platinum")) return 0.20;
        else throw new IllegalArgumentException("unknown tier: " + tier);
    }

    public static double finalPrice(String tier, double amount) {
        double rate;
        if (tier.equals("bronze")) rate = 0.00;
        else if (tier.equals("silver")) rate = 0.05;
        else if (tier.equals("gold")) rate = 0.10;
        else if (tier.equals("platinum")) rate = 0.20;
        else throw new IllegalArgumentException("unknown tier: " + tier);
        return Math.round(amount * (1 - rate) * 100.0) / 100.0;
    }

    public static String tierBadge(String tier) {
        if (tier.equals("bronze")) return "BRONZE MEMBER";
        else if (tier.equals("silver")) return "SILVER MEMBER";
        else if (tier.equals("gold")) return "GOLD MEMBER";
        else if (tier.equals("platinum")) return "PLATINUM MEMBER";
        else throw new IllegalArgumentException("unknown tier: " + tier);
    }
}

