public final class PricingTest {
    public static void main(String[] args) {
        checkRate("bronze", 0.00);
        checkRate("silver", 0.05);
        checkRate("gold", 0.10);
        checkRate("platinum", 0.20);

        checkPrice("gold", 19.99, 17.99);      // 19.99 * 0.9 = 17.991 -> 17.99
        checkPrice("silver", 100.0, 95.0);
        checkPrice("bronze", 12.34, 12.34);
        checkPrice("platinum", 250.0, 200.0);

        checkBadge("bronze", "BRONZE MEMBER");
        checkBadge("platinum", "PLATINUM MEMBER");

        expectThrow(() -> Pricing.discountRate("wood"));
        expectThrow(() -> Pricing.finalPrice("wood", 10.0));
        expectThrow(() -> Pricing.tierBadge("wood"));

        System.out.println("all tests passed");
    }

    static void checkRate(String tier, double expected) {
        double got = Pricing.discountRate(tier);
        if (got != expected) {
            throw new AssertionError("discountRate(" + tier + ") = " + got + ", expected " + expected);
        }
    }

    static void checkPrice(String tier, double amount, double expected) {
        double got = Pricing.finalPrice(tier, amount);
        if (got != expected) {
            throw new AssertionError("finalPrice(" + tier + ", " + amount + ") = " + got
                    + ", expected " + expected);
        }
    }

    static void checkBadge(String tier, String expected) {
        String got = Pricing.tierBadge(tier);
        if (!expected.equals(got)) {
            throw new AssertionError("tierBadge(" + tier + ") = " + got + ", expected " + expected);
        }
    }

    static void expectThrow(Runnable r) {
        try {
            r.run();
        } catch (IllegalArgumentException e) {
            if (!String.valueOf(e.getMessage()).contains("wood")) {
                throw new AssertionError("exception message must name the bad tier, got: " + e.getMessage());
            }
            return;
        }
        throw new AssertionError("unknown tier must throw IllegalArgumentException");
    }
}

