import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

public final class CheckPricing {
    public static void main(String[] args) throws Exception {
        List<String> cmd = new ArrayList<>(List.of("javac"));
        try (Stream<Path> files = Files.list(Path.of("."))) {
            files.map(Path::getFileName).map(Path::toString)
                 .filter(n -> n.endsWith(".java") && !n.equals("CheckPricing.java"))
                 .sorted()
                 .forEach(cmd::add);
        }
        if (exec(cmd.toArray(new String[0])) != 0) {
            System.err.println("compilation failed");
            System.exit(1);
        }
        System.exit(exec("java", "-ea", "PricingTest"));
    }

    static int exec(String... cmd) throws IOException, InterruptedException {
        return new ProcessBuilder(cmd).inheritIO().start().waitFor();
    }
}

