public final class Pricing {
    private Pricing() {}

    enum Tier {
        BRONZE(0.00, "BRONZE MEMBER"),
        SILVER(0.05, "SILVER MEMBER"),
        GOLD(0.10, "GOLD MEMBER"),
        PLATINUM(0.20, "PLATINUM MEMBER");

        final double rate;
        final String badge;

        Tier(double rate, String badge) {
            this.rate = rate;
            this.badge = badge;
        }

        static Tier fromString(String tier) {
            for (Tier t : values()) {
                if (t.name().toLowerCase().equals(tier)) {
                    return t;
                }
            }
            throw new IllegalArgumentException("unknown tier: " + tier);
        }
    }

    public static double discountRate(String tier) {
        return Tier.fromString(tier).rate;
    }

    public static double finalPrice(String tier, double amount) {
        double rate = Tier.fromString(tier).rate;
        return Math.round(amount * (1 - rate) * 100.0) / 100.0;
    }

    public static String tierBadge(String tier) {
        return Tier.fromString(tier).badge;
    }
}

